import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 9

    try:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    except csv.Error:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False))

    records = [row for row in records if row and any(value.strip() for value in row)]
    if not records:
        return {"columns": [f"column_{i}" for i in range(1, expected_width + 1)], "rows": []}

    def is_numeric(value: str) -> bool:
        value = value.strip()
        return bool(value) and bool(re.fullmatch(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?", value))

    # Skip leading one-field textual preamble lines when structured records follow.
    first_structured = next(
        (i for i, row in enumerate(records) if len(row) > 1 or is_numeric(row[0])),
        len(records),
    )
    if first_structured:
        records = records[first_structured:]

    if not records:
        return {"columns": [f"column_{i}" for i in range(1, expected_width + 1)], "rows": []}

    has_header = False
    if len(records) > 1 and len(records[0]) == expected_width:
        first = records[0]
        second = records[1]
        has_header = (
            any(re.search(r"[A-Za-z]", value) for value in first)
            and not all(is_numeric(value) for value in first)
            and sum(is_numeric(value) for value in second) >= max(1, len(second) // 2)
        )

    if has_header:
        columns = [value.strip() for value in records[0]]
        data = records[1:]
    else:
        columns = []
        data = records

    width = max([expected_width, len(columns)] + [len(row) for row in data])
    if not columns:
        columns = [f"column_{i}" for i in range(1, width + 1)]
    else:
        columns.extend(f"column_{i}" for i in range(len(columns) + 1, width + 1))

    normalized_rows = [row + [""] * (width - len(row)) for row in data]
    return {"columns": columns, "rows": normalized_rows}
